// Find the uploaded file's binary, detect its extension, and re-key it to 'data'
const item = $input.first();
const binary = item.binary || {};
const keys = Object.keys(binary);
if (keys.length === 0) {
  throw new Error('No file was uploaded in the form submission.');
}
const file = binary[keys[0]];
const fileName = file.fileName || '';
const fileExt = (fileName.split('.').pop() || '').toLowerCase();
return [{ json: { fileName, fileExt }, binary: { data: file } }];

// Clean the extracted rows (equivalent to a Pandas cleaning step)
const rows = $input.all().map(i => i.json);

const cleaned = [];
const seen = new Set();

for (const row of rows) {
  const out = {};
  for (const [key, value] of Object.entries(row)) {
    let v = value;
    // Trim strings and normalize empty values to null
    if (typeof v === 'string') {
      v = v.trim();
      if (v === '') v = null;
    }
    out[key] = v;
  }

  // Drop rows where every value is null/empty
  const hasValue = Object.values(out).some(v => v !== null && v !== undefined);
  if (!hasValue) continue;

  // Drop exact duplicate rows
  const sig = JSON.stringify(out);
  if (seen.has(sig)) continue;
  seen.add(sig);

  cleaned.push(out);
}

return cleaned.map(json => ({ json }));

// Build an auto-computed business-insights summary from the cleaned rows.
const rows = $('Clean Data').all().map(i => i.json);
const insights = [];

insights.push({ Metric: 'Total Rows', Column: '(all)', Value: rows.length });

if (rows.length === 0) {
  return insights.map(json => ({ json }));
}

// Determine all column names present
const columns = Array.from(rows.reduce((set, r) => {
  Object.keys(r).forEach(k => set.add(k));
  return set;
}, new Set()));

const isNumeric = (v) => v !== null && v !== undefined && v !== '' && !isNaN(Number(v));

for (const col of columns) {
  const values = rows.map(r => r[col]).filter(v => v !== null && v !== undefined && v !== '');
  const numericVals = values.filter(isNumeric).map(Number);

  // Treat as numeric column if a clear majority of non-empty values are numbers
  if (values.length > 0 && numericVals.length >= values.length * 0.7) {
    const sum = numericVals.reduce((a, b) => a + b, 0);
    const avg = numericVals.length ? sum / numericVals.length : 0;
    const round = (n) => Math.round(n * 100) / 100;
    insights.push({ Metric: 'Sum', Column: col, Value: round(sum) });
    insights.push({ Metric: 'Average', Column: col, Value: round(avg) });
    insights.push({ Metric: 'Min', Column: col, Value: round(Math.min(...numericVals)) });
    insights.push({ Metric: 'Max', Column: col, Value: round(Math.max(...numericVals)) });
    insights.push({ Metric: 'Count (non-empty)', Column: col, Value: numericVals.length });
  } else if (values.length > 0) {
    // Categorical column: distinct count + top value
    const freq = {};
    for (const v of values) {
      const key = String(v);
      freq[key] = (freq[key] || 0) + 1;
    }
    const sorted = Object.entries(freq).sort((a, b) => b[1] - a[1]);
    insights.push({ Metric: 'Distinct Values', Column: col, Value: sorted.length });
    if (sorted.length) {
      insights.push({ Metric: 'Top Value', Column: col, Value: sorted[0][0] });
      insights.push({ Metric: 'Top Value Count', Column: col, Value: sorted[0][1] });
    }
  }
}

return insights.map(json => ({ json }));

// Combine both generated Excel files onto a single item for the email.
const insightsBin = $('Generate Insights Excel').first().binary.insights;
const dataBin = $('Generate Excel Report').first().binary.data;
return [{ json: {}, binary: { data: dataBin, insights: insightsBin } }];
